class BattleAnimationPreview : public QWidget
{
public:
    explicit BattleAnimationPreview(QWidget* parent=nullptr):QWidget(parent){setMinimumHeight(260);setAutoFillBackground(false);}
    void setDefinition(const game::BattleAnimationDefinition& definition,const QString& projectRoot){m_definition=definition;m_root=projectRoot;update();}
    void setTime(int ms){m_time=qMax(0,ms);update();}
protected:
    void paintEvent(QPaintEvent*) override
    {
        QPainter p(this);p.setRenderHint(QPainter::Antialiasing);p.fillRect(rect(),QColor("#111827"));
        const QRectF arena=QRectF(rect()).adjusted(18,18,-18,-18);p.setPen(QColor("#334155"));p.setBrush(QColor("#172033"));p.drawRoundedRect(arena,10,10);
        const QPointF anchor=arena.center();
        for(const game::BattleAnimationCue& cue:m_definition.cues){if(cue.type==QLatin1String("se")||cue.type==QLatin1String("shake"))continue;if(m_time<cue.timeMs||m_time>=cue.timeMs+cue.durationMs)continue;const int local=m_time-cue.timeMs;const qreal progress=qBound(0.0,qreal(local)/qMax(1,cue.durationMs),1.0);const QPointF center=anchor+cue.offset;
            if(cue.type==QLatin1String("picture")){
                QImage image;const QString path=QFileInfo(cue.assetPath).isAbsolute()?cue.assetPath:QDir(m_root).filePath(cue.assetPath);image.load(path);if(image.isNull()){p.setPen(QColor("#f59e0b"));p.drawText(QRectF(center.x()-100,center.y()-20,200,40),Qt::AlignCenter,tr("Picture não carregada"));continue;}const int cols=qMax(1,cue.columns),rows=qMax(1,cue.rows),frame=game::battleAnimationFrame(cue,local),fw=qMax(1,image.width()/cols),fh=qMax(1,image.height()/rows);const QRect source((frame%cols)*fw,(frame/cols)*fh,fw,fh);QSizeF size(cue.size.width()*cue.scale,cue.size.height()*cue.scale);QRectF target(center.x()-size.width()/2,center.y()-size.height()/2,size.width(),size.height());p.save();p.setOpacity(cue.opacity);p.translate(target.center());p.rotate(cue.rotation);p.translate(-target.center());p.drawImage(target,image,source);p.restore();
            }else if(cue.type==QLatin1String("particle")){
                const int count=qBound(1,cue.particleCount,150);const qreal spread=qDegreesToRadians(cue.spreadDegrees);for(int i=0;i<count;++i){const qreal u=count<=1?.5:qreal(i)/(count-1);const qreal angle=(u-.5)*spread+i*.37;const qreal distance=cue.speed*(local/1000.0);const QPointF pos=center+QPointF(qCos(angle)*distance,qSin(angle)*distance);QColor c=cue.color;c.setAlphaF(qBound(0.0,cue.opacity*(1.0-progress),1.0));p.setPen(Qt::NoPen);p.setBrush(c);const qreal radius=qMax(2.0,3.0+cue.strength*.25);if(cue.particleShape==QLatin1String("square"))p.drawRect(QRectF(pos.x()-radius,pos.y()-radius,radius*2,radius*2));else p.drawEllipse(pos,radius,radius);}
            }else if(cue.type==QLatin1String("flash")){QColor c=cue.color;c.setAlphaF(qBound(0.0,cue.opacity*(1.0-progress),1.0));p.fillRect(rect(),c);}
        }
        p.setPen(QColor("#94a3b8"));p.drawText(QRectF(10,height()-25,width()-20,20),Qt::AlignCenter,tr("Prévia: %1 ms / impacto: %2 ms").arg(m_time).arg(m_definition.hitFrameMs));
    }
private:
    game::BattleAnimationDefinition m_definition;QString m_root;int m_time=0;
};

QSpinBox* spin(QWidget* parent,int min,int max,int value=0){auto* s=new QSpinBox(parent);s->setRange(min,max);s->setValue(value);return s;}

QString cueLabel(const game::BattleAnimationCue& cue,int index)
{
    QString type=cue.type;if(type==QLatin1String("picture"))type=QObject::tr("Picture/Spritesheet");else if(type==QLatin1String("particle"))type=QObject::tr("Partículas");else if(type==QLatin1String("se"))type=QObject::tr("SE");else if(type==QLatin1String("flash"))type=QObject::tr("Flash");else if(type==QLatin1String("shake"))type=QObject::tr("Tremor");return QObject::tr("%1. %2 — %3 ms").arg(index+1).arg(type).arg(cue.timeMs);
}

