class RpgAnimationEditorDialog::Impl
{
public:
    core::Editor& editor;game::BattleAnimationDefinition definition;QListWidget* list=nullptr;QSpinBox *duration=nullptr,*hit=nullptr,*time=nullptr,*cueDuration=nullptr,*frames=nullptr,*columns=nullptr,*rows=nullptr,*width=nullptr,*height=nullptr,*offsetX=nullptr,*offsetY=nullptr,*opacity=nullptr,*scale=nullptr,*rotation=nullptr,*particles=nullptr,*speed=nullptr,*spread=nullptr,*strength=nullptr,*volume=nullptr;QComboBox *type=nullptr,*shape=nullptr;QLineEdit* asset=nullptr;QCheckBox* loop=nullptr;QPushButton* color=nullptr;BattleAnimationPreview* preview=nullptr;QSlider* scrub=nullptr;QTimer timer;bool playing=false,loading=false;int current=-1;
    explicit Impl(core::Editor& e):editor(e){}
    void rebuildList(){list->clear();for(int i=0;i<definition.cues.size();++i)list->addItem(cueLabel(definition.cues[i],i));if(!definition.cues.isEmpty()){current=qBound(0,current,definition.cues.size()-1);list->setCurrentRow(current);}else current=-1;}
    void loadCue(){loading=true;current=list->currentRow();if(current<0||current>=definition.cues.size()){loading=false;return;}const auto& c=definition.cues[current];type->setCurrentIndex(qMax(0,type->findData(c.type)));time->setValue(c.timeMs);cueDuration->setValue(c.durationMs);asset->setText(c.assetPath);frames->setValue(c.frames);columns->setValue(c.columns);rows->setValue(c.rows);loop->setChecked(c.loop);width->setValue(qRound(c.size.width()));height->setValue(qRound(c.size.height()));offsetX->setValue(qRound(c.offset.x()));offsetY->setValue(qRound(c.offset.y()));opacity->setValue(qRound(c.opacity*100));scale->setValue(qRound(c.scale*100));rotation->setValue(qRound(c.rotation));particles->setValue(c.particleCount);speed->setValue(qRound(c.speed));spread->setValue(qRound(c.spreadDegrees));strength->setValue(qRound(c.strength));volume->setValue(c.volume);shape->setCurrentIndex(qMax(0,shape->findData(c.particleShape)));color->setProperty("battleColor",c.color);color->setStyleSheet(QStringLiteral("background:%1").arg(c.color.name()));loading=false;refreshPreview();}
    void saveCue(){if(loading||current<0||current>=definition.cues.size())return;auto& c=definition.cues[current];c.type=type->currentData().toString();c.timeMs=time->value();c.durationMs=cueDuration->value();c.assetPath=asset->text();c.frames=frames->value();c.columns=columns->value();c.rows=rows->value();c.loop=loop->isChecked();c.size=QSizeF(width->value(),height->value());c.offset=QPointF(offsetX->value(),offsetY->value());c.opacity=opacity->value()/100.0;c.scale=scale->value()/100.0;c.rotation=rotation->value();c.particleCount=particles->value();c.speed=speed->value();c.spreadDegrees=spread->value();c.strength=strength->value();c.volume=volume->value();c.particleShape=shape->currentData().toString();c.color=color->property("battleColor").value<QColor>();definition.durationMs=duration->value();definition.hitFrameMs=qBound(0,hit->value(),definition.durationMs);rebuildList();refreshPreview();}
    void refreshPreview(){definition.durationMs=duration->value();definition.hitFrameMs=qBound(0,hit->value(),definition.durationMs);scrub->setMaximum(definition.durationMs);preview->setDefinition(definition,editor.projectRoot());preview->setTime(scrub->value());}
};

