class EnemyAiEditorDialog::Impl{public:QVector<core::DatabaseRecord> skills,states;QTableWidget* table=nullptr;};
EnemyAiEditorDialog::EnemyAiEditorDialog(const QVector<core::DatabaseRecord>& skills,const QVector<core::DatabaseRecord>& states,const QVariantList& rules,QWidget* parent):QDialog(parent),m_impl(new Impl)
{
    m_impl->skills=skills;m_impl->states=states;setWindowTitle(tr("IA do inimigo — Regras visuais"));resize(1000,520);auto* root=new QVBoxLayout(this);root->addWidget(new QLabel(tr("A IA escolhe entre as regras válidas usando o Peso. Se nenhuma regra casar, usa Ataque normal."),this));m_impl->table=new QTableWidget(this);m_impl->table->setColumnCount(7);m_impl->table->setHorizontalHeaderLabels({tr("Habilidade"),tr("Peso"),tr("HP mín %"),tr("HP máx %"),tr("MP mín"),tr("A cada N turnos"),tr("Estado exigido")});m_impl->table->horizontalHeader()->setSectionResizeMode(QHeaderView::Stretch);root->addWidget(m_impl->table,1);auto* add=new QPushButton(tr("+ Regra"),this);auto* del=new QPushButton(tr("Remover regra"),this);auto* row=new QHBoxLayout;row->addWidget(add);row->addWidget(del);row->addStretch();root->addLayout(row);auto* buttons=new QDialogButtonBox(QDialogButtonBox::Ok|QDialogButtonBox::Cancel,this);root->addWidget(buttons);connect(buttons,&QDialogButtonBox::accepted,this,&QDialog::accept);connect(buttons,&QDialogButtonBox::rejected,this,&QDialog::reject);
    auto addRow=[this](const game::BattleAiRule& rule){const int r=m_impl->table->rowCount();m_impl->table->insertRow(r);auto* skill=new QComboBox(m_impl->table);skill->addItem(tr("(Ataque normal / nenhuma regra)"),QString());for(const auto& rec:m_impl->skills)skill->addItem(rec.name,rec.id);skill->setCurrentIndex(qMax(0,skill->findData(rule.skillId)));m_impl->table->setCellWidget(r,0,skill);for(int c=1;c<=5;++c){auto* s=spin(m_impl->table,c==1?1:0,c==1?9999:(c==4?999999:100),0);if(c==1)s->setValue(rule.weight);if(c==2)s->setValue(rule.hpMinPercent);if(c==3)s->setValue(rule.hpMaxPercent);if(c==4)s->setValue(rule.mpMin);if(c==5){s->setRange(1,999);s->setValue(rule.everyTurns);}m_impl->table->setCellWidget(r,c,s);}auto* state=new QComboBox(m_impl->table);state->addItem(tr("(nenhum)"),QString());for(const auto& rec:m_impl->states)state->addItem(rec.name,rec.id);state->setCurrentIndex(qMax(0,state->findData(rule.requiredStateId)));m_impl->table->setCellWidget(r,6,state);};for(const QVariant& v:rules)addRow(game::BattleAiRule::fromVariant(v.toMap()));connect(add,&QPushButton::clicked,this,[addRow]{addRow(game::BattleAiRule{});});connect(del,&QPushButton::clicked,this,[this]{const int r=m_impl->table->currentRow();if(r>=0)m_impl->table->removeRow(r);});if(m_impl->table->rowCount()==0)addRow(game::BattleAiRule{});
}
EnemyAiEditorDialog::~EnemyAiEditorDialog(){delete m_impl;}

QVariantList EnemyAiEditorDialog::rules() const{QVariantList out;for(int r=0;r<m_impl->table->rowCount();++r){game::BattleAiRule rule;rule.skillId=qobject_cast<QComboBox*>(m_impl->table->cellWidget(r,0))->currentData().toString();rule.weight=qobject_cast<QSpinBox*>(m_impl->table->cellWidget(r,1))->value();rule.hpMinPercent=qobject_cast<QSpinBox*>(m_impl->table->cellWidget(r,2))->value();rule.hpMaxPercent=qobject_cast<QSpinBox*>(m_impl->table->cellWidget(r,3))->value();rule.mpMin=qobject_cast<QSpinBox*>(m_impl->table->cellWidget(r,4))->value();rule.everyTurns=qobject_cast<QSpinBox*>(m_impl->table->cellWidget(r,5))->value();rule.requiredStateId=qobject_cast<QComboBox*>(m_impl->table->cellWidget(r,6))->currentData().toString();if(!rule.skillId.isEmpty())out.push_back(rule.toVariant());}return out;}

